/**
 *
 * Template Cone
 *
 */

// ------------------------------------------------
// C U S T O M I Z E    T H E    A N I M A T I O N
// ------------------------------------------------
//
const ANIMATION1 = 'blfx.spell.cast.swirl1.fire1.orange';
const SCALE1 = 1.5; // Size of the animation. Default value: 1.5
const FADEIN1 = 0;
const FADEOUT1 = 0;
const OPACITY1 = 1;
const COLORMATRIX_HUE1 = 0;
const WAIT_UNTIL_FINISHED1 = -600; // Default value: -600
const WAIT_UNTIL_FINISHED_ENABLED1 = true;
const ENABLED1 = false;
const SOUND_ENABLED1 = false;
const SOUND1 = 'blfx.sound.spell.cast.generic.1';
const DELAY_SOUND1 = 0; // Default value: 0
const START_TIME_SOUND1 = 0; // Default value: 0
const WAIT_UNTIL_FINISHED_SOUND_ENABLED1 = false;
const WAIT_UNTIL_FINISHED_SOUND1 = 0;

const ANIMATION2 = 'blfx.spell.range.ray.burst4.fire.impact1.intro.yellow';
const OPACITY2 = 1;
const COLORMATRIX_HUE2 = 0;
const WAIT_UNTIL_FINISHED2 = -500; // Default value: -500
const WAIT_UNTIL_FINISHED_ENABLED2 = true;
const ENABLED2 = false;
const SOUND_ENABLED2 = false;
const SOUND2 = 'blfx.sound.spell.cast.fire_bolt.1';
const DELAY_SOUND2 = 0; // Default value: 0
const START_TIME_SOUND2 = 0; // Default value: 0
const WAIT_UNTIL_FINISHED_SOUND_ENABLED2 = false;
const WAIT_UNTIL_FINISHED_SOUND2 = 0;

const ANIMATION3 = 'blfx.spell.template.cone.breath_weapon2.cold.color1';
const BELOW_TOKENS3 = false;
const FADEIN3 = 0;
const FADEOUT3 = 0;
const OPACITY3 = 1;
const COLORMATRIX_HUE3 = 0;
const HIDDEN_TEMPLATE3 = false;
const DELETE_TEMPLATE3 = true;
const ENABLED3 = true;
const SOUND_ENABLED3 = false;
const SOUND3 = 'blfx.sound.spell.cast.burning_hands.3';
const DELAY_SOUND3 = 0; // Default value: 0
const START_TIME_SOUND3 = 0; // Default value: 0
const WAIT_UNTIL_FINISHED_SOUND_ENABLED3 = false;
const WAIT_UNTIL_FINISHED_SOUND3 = 0;
//
// ------------------------------------------------

await blfx.helpers.wait(200);

if (typeof templateDocument === 'undefined' || templateDocument === null) return;

if (HIDDEN_TEMPLATE3) {
  await blfx.helpers.setDocumentVisibility(templateDocument);
}

const templateElevation = blfx.helpers.getCombinedDocElevation(sourceToken, templateDocument);
const sourceTokenElevation = blfx.helpers.getDocumentElevation(sourceToken);

await new Sequence()

  // ON SOURCE TOKEN
  .sound()
  .playIf(SOUND_ENABLED1)
  .file(SOUND1)
  .delay(DELAY_SOUND1)
  .startTime(START_TIME_SOUND1)
  .preset('conditionalWait', [WAIT_UNTIL_FINISHED_SOUND_ENABLED1, WAIT_UNTIL_FINISHED_SOUND1])

  .effect()
  .playIf(ENABLED1)
  .atLocation(sourceToken)
  .file(ANIMATION1)
  .elevation(sourceTokenElevation)
  .scaleToObject(SCALE1)
  .fadeIn(FADEIN1)
  .fadeOut(FADEOUT1)
  .opacity(OPACITY1)
  .filter('ColorMatrix', { hue: COLORMATRIX_HUE1 })
  .center()
  .rotateTowards(templateDocument)
  .preset('conditionalWait', [WAIT_UNTIL_FINISHED_ENABLED1, WAIT_UNTIL_FINISHED1])

  // FROM SOURCE TO TARGET
  .sound()
  .playIf(SOUND_ENABLED2)
  .file(SOUND2)
  .delay(DELAY_SOUND2)
  .startTime(START_TIME_SOUND2)
  .preset('conditionalWait', [WAIT_UNTIL_FINISHED_SOUND_ENABLED2, WAIT_UNTIL_FINISHED_SOUND2])

  .effect()
  .playIf(ENABLED2)
  .file(ANIMATION2)
  .opacity(OPACITY2)
  .filter('ColorMatrix', { hue: COLORMATRIX_HUE2 })
  .atLocation(sourceToken)
  .stretchTo({ x: templateDocument.x, y: templateDocument.y })
  .preset('conditionalWait', [WAIT_UNTIL_FINISHED_ENABLED2, WAIT_UNTIL_FINISHED2])

  // ON TARGET
  .sound()
  .playIf(SOUND_ENABLED3)
  .file(SOUND3)
  .delay(DELAY_SOUND3)
  .startTime(START_TIME_SOUND3)
  .preset('conditionalWait', [WAIT_UNTIL_FINISHED_SOUND_ENABLED3, WAIT_UNTIL_FINISHED_SOUND3])

  .effect()
  .playIf(ENABLED3)
  .file(ANIMATION3)
  .fadeIn(FADEIN3)
  .fadeOut(FADEOUT3)
  .opacity(OPACITY3)
  .filter('ColorMatrix', { hue: COLORMATRIX_HUE3 })
  .attachTo(templateDocument, { bindVisibility: false, bindScale: false })
  .stretchTo(templateDocument)
  .elevation(templateElevation)
  .belowTokens(BELOW_TOKENS3)
  .waitUntilFinished()
  .play();

if (ENABLED3 && DELETE_TEMPLATE3) {
  await templateDocument?.delete();
